gA7(){return"\u062a\u062a\u063a\u064a\u0631 \u0627\u0644\u0644\u063a\u0629 \u0641\u0648\u0631\u064b\u0627 \u0641\u064a \u0643\u0627\u0645\u0644 \u0627\u0644\u062a\u0637\u0628\u064a\u0642."},
gpT(){return"\u0625\u062c\u0645\u0627\u0644\u064a \u0627\u0644\u062a\u0634\u063a\u064a\u0644\u0627\u062a"},
gpN(){return"\u0639\u0636\u0648 \u0645\u0646\u0630"},
gpJ(){return"\u0627\u0644\u062f\u0648\u0644\u0629"},
gpG(){return"\u0627\u0644\u0641\u0646\u0627\u0646 \u0631\u0642\u0645 1 (\u0627\u0644\u0623\u0633\u0628\u0648\u0639)"},
gpE(){return"\u0627\u0644\u0623\u0644\u0628\u0648\u0645 \u0631\u0642\u0645 1 (\u0627\u0644\u0623\u0633\u0628\u0648\u0639)"},
gpV(){return"\u0627\u0644\u0645\u0642\u0637\u0639 \u0631\u0642\u0645 1 (\u0627\u0644\u0623\u0633\u0628\u0648\u0639)"},
gpX(){return"\u0641\u0646\u0627\u0646\u0648\u0646 \u0641\u0631\u064a\u062f\u0648\u0646"},
gpY(){return"\u0645\u0642\u0627\u0637\u0639 \u0641\u0631\u064a\u062f\u0629"},
gpW(){return"\u0623\u0644\u0628\u0648\u0645\u0627\u062a \u0641\u0631\u064a\u062f\u0629"},
gxO(){return"\u0647\u0630\u0627 \u0627\u0644\u0623\u0633\u0628\u0648\u0639"},
gxq(){return"\u064a"},
gtn(){return"\u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u0645\u0641\u0636\u0644\u0629 (\u0627\u062e\u062a\u064a\u0627\u0631\u064a)"},
gtp(){return"\u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a \u064a\u062a\u064a\u062d \u0644\u0644\u062a\u0637\u0628\u064a\u0642 \u0625\u0636\u0627\u0641\u0629 \u0623\u0648 \u0625\u0632\u0627\u0644\u0629 \u0627\u0644\u0645\u0642\u0637\u0648\u0639\u0627\u062a \u0645\u0646 \u0627\u0644\u0645\u0641\u0636\u0644\u0629 \u0645\u0628\u0627\u0634\u0631\u0629 \u0639\u0644\u0649 Last.fm."},
gtu(){return"\u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a \u0644\u0640 Last.fm"},
gzd(){return"\u064a\u062c\u0628 \u0623\u0646 \u064a\u062a\u0643\u0648\u0646 \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0627\u0644\u0633\u0631\u064a \u0645\u0646 32 \u062d\u0631\u0641\u064b\u0627."},
