guZ(){return"\u0625\u062c\u0645\u0627\u0644\u064a \u0627\u0644\u062a\u0634\u063a\u064a\u0644\u0627\u062a \u0644\u0643\u0644 \u0627\u0644\u0641\u0646\u0627\u0646\u064a\u0646."},
guX(){return"\u0639\u062f\u062f \u0627\u0644\u0641\u0646\u0627\u0646\u064a\u0646 \u0627\u0644\u0645\u062e\u062a\u0644\u0641\u064a\u0646 \u0627\u0644\u0630\u064a\u0646 \u0627\u0633\u062a\u0645\u0639\u062a \u0625\u0644\u064a\u0647\u0645 \u0645\u0631\u0629 \u0648\u0627\u062d\u062f\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644."},
guW(){return"\u0639\u062f\u062f \u0627\u0644\u0623\u0644\u0628\u0648\u0645\u0627\u062a \u0627\u0644\u0645\u062e\u062a\u0644\u0641\u0629 \u0627\u0644\u062a\u064a \u0627\u0633\u062a\u0645\u0639\u062a \u0625\u0644\u064a\u0647\u0627 \u0645\u0631\u0629 \u0648\u0627\u062d\u062f\u0629 \u0639\u0644\u0649 \u0627\u0644\u0623\u0642\u0644."},
